const verification=fs.readFileSync('docs/VERIFICATION.md','utf8');
assert.equal(verification.split(record.verificationAppend).length-1,1);
assert.deepEqual(identity(Buffer.from(verification.replace(record.verificationAppend,''))),record.baseline.local['docs/VERIFICATION.md']);
const placement=JSON.parse(record.checks.placement.result.output);
