 assert.equal(source,d.sourceText);
 const text=fs.readFileSync(d.target,'utf8');
 assert.ok(text.startsWith(d.cover));
 let restored=text.slice(d.cover.length);
 for(const pair of [...d.linkRebases].reverse()) {
