for(const file of files){const absolute=path.resolve(root,file),source=fs.readFileSync(absolute,'utf8');let count=0;for(const match of source.matchAll(/\]\(([^)\s#]*)(#[^)\s]+)?\)/gu)){const [,ref,fragment]=match;if(/^[a-z][a-z0-9+.-]*:/iu.test(ref))continue;count++;const target=ref?path.resolve(path.dirname(absolute),ref):absolute;if(!fs.existsSync(target)){brokenLinks.push({file,ref,fragment,reason:'missing-file'});continue;}if(fragment&&target.endsWith('.md')&&!anchors(fs.readFileSync(target,'utf8')).has(fragment.slice(1)))brokenLinks.push({file,ref,fragment,reason:'missing-anchor'});}localLinksChecked[file]=count;}
