const previous=new Set(record.baseline.repos.agp.status.split('\n').filter(Boolean));
const current=new Set(repos.agp.status.split('\n').filter(Boolean));
assert.deepEqual([...current].filter(line=>!previous.has(line)),['?? docs/reviews/upstream-feedback-handoff-checks.json']);
assert.deepEqual([...previous].filter(line=>!current.has(line)),[]);
const externalObserved=Object.fromEntries(Object.keys(record.baseline.external).map(p=>[p,stat(p)]));
